<script setup>
import {Head,useForm} from '@inertiajs/vue3';
const props=defineProps({registrationToken:String,maskedEmail:String,retryAfter:Number});
const form=useForm({registration_token:props.registrationToken,code:''}); const resend=useForm({registration_token:props.registrationToken});
const verify=()=>form.post(route('membership.verify')); const sendAgain=()=>resend.post(route('membership.verify.resend'));
</script>
<template><Head title="Verifica tu correo"/><main><section><div class="icon">✉</div><span>VERIFICACIÓN</span><h1>Revisa tu correo</h1><p>Enviamos un código de 6 dígitos a <b>{{maskedEmail}}</b>.</p><form @submit.prevent="verify"><input v-model="form.code" inputmode="numeric" maxlength="6" pattern="[0-9]{6}" autocomplete="one-time-code" placeholder="000000" autofocus required><small>{{form.errors.code}}</small><button :disabled="form.processing">Verificar y activar cuponera →</button></form><button class="resend" :disabled="resend.processing" @click="sendAgain">Enviar un código nuevo</button><small>{{resend.errors.code}}</small></section></main></template>
<style scoped>main{min-height:100vh;background:#332820;display:grid;place-items:center;padding:20px;color:#332820}section{width:min(440px,100%);background:#fffaf1;text-align:center;padding:40px;border-radius:22px;box-shadow:0 20px 60px #0008}.icon{width:70px;height:70px;border-radius:50%;display:grid;place-items:center;margin:auto;background:#eee4d2;font-size:30px}span{display:block;color:#993b2a;letter-spacing:.2em;font-size:10px;font-weight:800;margin-top:20px}h1{font:38px Georgia;margin:8px}p{color:#756b62}input{display:block;width:100%;font-size:30px;letter-spacing:.4em;text-align:center;padding:14px;border:1px solid #d9cdbd;border-radius:10px;margin-top:25px}button{width:100%;padding:14px;border:0;border-radius:9px;background:#993b2a;color:white;font-weight:800;margin-top:15px}.resend{background:transparent;color:#576443;border:1px solid #576443}small{display:block;color:#993b2a;margin-top:6px}</style>
